owned_probe_diagnostic_GSC:
// OWNED PROBE ONLY: invoke real native damage on existing wave infantry.
// No production policy, health restoration, animation or lifecycle is replaced.
wounded_probe()
{
    players = getPlayers();
    if ( !players.size )
        return;
    players[ 0 ] codol_botPressButtons( 0, 60 );
    for ( spin = 0; spin < 30; spin++ )
    {
        waiting = maps\mp\gametypes\_survival_ai::living_enemies();
        if ( waiting.size )
            break;
        wait( 0.5 );
    }
    codolprintln( "CoDOL survivaltest: WOUND_PROBE_STARTED" );
    enemies = maps\mp\gametypes\_survival_ai::living_enemies();
    for ( i = 0; i < enemies.size; i++ )
    {
        e = enemies[ i ];
        if ( !isDefined( e ) || !isAlive( e ) || ( isDefined( e.isdog ) && e.isdog ) )
            continue;
        remaining = int( e.maxhealth * 0.3 );
        if ( remaining > 30 )
            remaining = 30;
        if ( remaining < 2 )
            remaining = 2;
        amount = e.health - remaining;
        if ( amount < 1 )
            amount = 1;
        for ( shot = 0; shot < 16 && isDefined( e ) && isAlive( e ) && e.health > 1; shot++ )
        {
            e finishActorDamage( undefined, players[ 0 ], amount, 0, "MOD_RIFLE_BULLET", "none", e.origin, ( 1, 0, 0 ), "torso_lower", 0 );
            amount = 1;
            wait( 1.6 );
            if ( isDefined( e ) && isAlive( e ) && isDefined( e.coop_wounded_kind ) )
            {
                beforeKills = players[ 0 ].kills;
                beforeWaveKills = level.survival_killed;
                living = maps\mp\gametypes\_survival_ai::living_enemies();
                codolprintln( "CoDOL survivaltest: WOUND_LIVE ent " + e getEntityNumber() + " hp " + e.health + " alive " + isAlive( e ) + " kind " + e.coop_wounded_kind + " living " + living.size + " wavekilled " + beforeWaveKills + " playerkills " + beforeKills );
                wait( 0.3 );
                if ( !isDefined( e ) || !isAlive( e ) )
                    return;
                e finishActorDamage( undefined, players[ 0 ], e.health, 0, "MOD_RIFLE_BULLET", "none", e.origin, ( 1, 0, 0 ), "torso_lower", 0 );
                wait( 0.5 );
                living = maps\mp\gametypes\_survival_ai::living_enemies();
                codolprintln( "CoDOL survivaltest: WOUND_FINAL hp " + e.health + " alive " + isAlive( e ) + " living " + living.size + " wavekilldelta " + ( level.survival_killed - beforeWaveKills ) + " playerkilldelta " + ( players[ 0 ].kills - beforeKills ) );
                return;
            }
        }
    }
    codolprintln( "CoDOL survivaltest: WOUND_NOT_OBSERVED" );
}
